#if UNITY_EDITOR
using LastRail.Battle;
using NUnit.Framework;
using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
namespace LastRail.Tests.EditMode {
 public sealed class BSafeMaintenanceObservationSourceTests {
  const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/SafeMaintenanceObservation-20261005/";
  static BDirectAttackBasicLoop Native(){var f=BNamedOperatorSourceTests.Native();return f.adapter.CreateRuntime(f.binding,BOrdinaryGeometryTests.Geometry(f.binding),10000);}
  [Test] public void SavedRailObservationNeedsOriginalCommittedBoundary(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Battle.CombatSavedMaintenanceObservationSource"));}
  [Test] public void AcceptedRuntimeObservationNeedsSeparateSourceOwner(){Assert.NotNull(typeof(BDirectAttackInput).Assembly.GetType("LastRail.Battle.BSafeMaintenanceObservationSource"));}
  [Test] public void ActualPauseAndResumeAreAcceptedOnceAndOriginalClockOwnsTheStop(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){Assert.IsFalse((bool)s.Capture()["combatStopped"]);n.SetPaused("p",true);var p=s.ObserveAccepted("p",0);long tick=n.Tick;n.Advance("paused-step",10000000,500);s.ObserveAccepted("paused-step",1);Assert.AreEqual(tick,n.Tick);Assert.IsTrue((bool)p["combatStopped"]);n.SetPaused("p",true);Assert.Throws<InvalidOperationException>(()=>s.ObserveAccepted("p",2));n.SetPaused("resume",false);var r=s.ObserveAccepted("resume",2);Assert.IsFalse((bool)r["combatStopped"]);Assert.Throws<InvalidOperationException>(()=>s.RequireUnchanged(1,(string)p["nativeHash"]));Assert.IsFalse(s.CanPrepareTrustedMaintenance);}}
  [Test] public void ExactDuplicateObservationDoesNotAdvanceSourceRevision(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){n.SetPaused("p",true);var p=s.ObserveAccepted("p",0);n.SetPaused("p",true);Assert.IsTrue(JToken.DeepEquals(p,s.ObserveAccepted("p",1)));Assert.AreEqual(1,s.Revision);Assert.Throws<InvalidOperationException>(()=>s.ObserveAccepted("p",0));}}
  [Test] public void RejectedCommandPublishesNothingAndNeverClaimsSafe(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){var before=s.Capture();Assert.Throws<ArgumentOutOfRangeException>(()=>n.SetSpeed("invalid-speed",1));Assert.Throws<InvalidOperationException>(()=>s.ObserveAccepted("invalid-speed",0));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));Assert.Throws<InvalidOperationException>(()=>s.RequireTrustedMaintenance());}}
  [Test] public void CurrentNativeFenceRejectsOutOfBandResumeBeforeObservation(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){n.SetPaused("p",true);var p=s.ObserveAccepted("p",0);s.RequireUnchanged(1,(string)p["nativeHash"]);n.SetPaused("r",false);Assert.Throws<InvalidOperationException>(()=>s.RequireUnchanged(1,(string)p["nativeHash"]));s.ObserveAccepted("r",1);}}
  [Test] public void SkippedOrUnacceptedCommandCannotBePublishedAsSingleAcceptedTransition(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){n.SetPaused("one",true);Assert.Throws<InvalidOperationException>(()=>s.ObserveAccepted("unaccepted",0));Assert.AreEqual(0,s.Revision);n.SetPaused("two",false);Assert.Throws<InvalidOperationException>(()=>s.ObserveAccepted("two",0));Assert.AreEqual(0,s.Revision);}}
  [Test] public void ImmutableCaptureRetainsEveryOriginalHazardOwnerWithoutZeroAggregate(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){n.Advance("actual-step",10000000,500);var p=s.ObserveAccepted("actual-step",0);Assert.IsTrue(JToken.DeepEquals(n.Capture(),p["native"]));Assert.NotNull(p["native"]["enemyTiming"]);Assert.NotNull(p["native"]["gunnerIntercept"]);Assert.NotNull(p["native"]["waveEntry"]);Assert.AreEqual(JTokenType.Null,p["travelStopped"].Type);Assert.AreEqual(JTokenType.Null,p["residualHazards"].Type);Assert.AreEqual(JTokenType.Null,p["safeEventId"].Type);p["native"]["state"]["direct"]["clock"]["paused"]=true;Assert.IsFalse((bool)s.Capture()["combatStopped"]);Assert.IsTrue(JToken.DeepEquals(n.Capture(),s.Capture()["native"]));}}
  [Test] public void ActualLaunchedHazardAndItsTerminalChangeInvalidateOldCapture(){var n=Native();using(var s=new BSafeMaintenanceObservationSource(n)){JObject launched=null;string shot=null;for(int i=0;i<50;i++){var id="fly-"+i;n.Advance(id,10000000,500);var p=s.ObserveAccepted(id,s.Revision);var flying=p["native"]["gunnerIntercept"]["projectiles"].FirstOrDefault(x=>(string)x["terminal"]=="FLYING");if(flying!=null){launched=p;shot=(string)flying["id"];break;}}Assert.NotNull(launched,"actual native gunner launch required");bool resolved=false;for(int i=0;i<10;i++){var id="contact-"+i;n.Advance(id,10000000,500);Assert.Throws<InvalidOperationException>(()=>s.RequireUnchanged((long)launched["sourceRevision"],(string)launched["nativeHash"]));var p=s.ObserveAccepted(id,s.Revision);var old=p["native"]["gunnerIntercept"]["projectiles"].Single(x=>(string)x["id"]==shot);if((string)old["terminal"]!="FLYING"){resolved=true;File.WriteAllText(Qa+"actual-hazard-stages.json",new JObject{["launched"]=launched,["resolved"]=p}.ToString());break;}}Assert.IsTrue(resolved);Assert.AreEqual(JTokenType.Null,s.Capture()["residualHazards"].Type);}}
  [Test] public void RestoreUsesOriginalNativeReplayAndIndependentObservationHash(){var f=BNamedOperatorSourceTests.Native();var g=BOrdinaryGeometryTests.Geometry(f.binding);var n=f.adapter.CreateRuntime(f.binding,g,10000);using(var s=new BSafeMaintenanceObservationSource(n)){n.Advance("actual",10000000,500);var p=s.ObserveAccepted("actual",0);var cached=n.Capture();var restored=BDirectAttackBasicLoop.RestoreOrdinaryGeometryRuntime(cached,BDirectAttackInput.Digest(cached),f.binding,BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource,g,10000,false);using(var r=BSafeMaintenanceObservationSource.Restore(restored,p,BDirectAttackInput.Digest(p))){Assert.IsTrue(JToken.DeepEquals(p,r.Capture()));restored.SetPaused("restored-pause",true);Assert.AreEqual(2,(long)r.ObserveAccepted("restored-pause",1)["sourceRevision"]);}Assert.Throws<ArgumentException>(()=>BSafeMaintenanceObservationSource.Restore(restored,p,BDirectAttackInput.Digest(p)));Assert.Throws<ArgumentException>(()=>BSafeMaintenanceObservationSource.Restore(n,p,"foreign-hash"));var changed=(JObject)p.DeepClone();changed["travelStopped"]=true;Assert.Throws<ArgumentException>(()=>BSafeMaintenanceObservationSource.Restore(n,changed,BDirectAttackInput.Digest(changed)));}}
  [Test] public void ActualNativeTerminalIsObservedWithoutTurningItIntoSafeEligibility(){var receipt=BInterceptSourceTests.Read(BInterceptSourceTests.Sample());var b=BOrdinaryGeometryTests.Stress(BInterceptSourceTests.Sample());var g=BOrdinaryGeometryTests.Geometry(b,BOrdinaryGeometryTests.ShortCarAsset());var n=BDirectAttackBasicLoop.CreateOrdinaryGeometryRuntime(b,receipt.OriginalSource,g,10000,true);using(var s=new BSafeMaintenanceObservationSource(n)){JObject last=s.Capture();int hit=0;for(int i=0;i<60&&n.Outcome=="RUNNING";i++){var id="terminal-step-"+i;n.Advance(id,10000000,500);last=s.ObserveAccepted(id,s.Revision);foreach(var life in ((JArray)n.Capture()["boarding"]["lives"]).Where(x=>(bool)x["registered"]&&(bool)x["targetable"]).ToArray()){var state=n.Capture();string target=(string)life["id"];var frame=n.ObserveOrdinaryGeometry("op_kyle",target,n.Tick,(long)state["spatialSource"]["revision"],g.Hash);if(!(bool)frame["eligible"]||(long)state["state"]["direct"]["next"]["op_kyle"]>n.Tick)continue;var eventId="actual-terminal-hit-"+hit++;n.ApplyWaveBasic(eventId,"op_kyle",target,(long)life["generation"]);last=s.ObserveAccepted(eventId,s.Revision);}}Assert.AreEqual("VICTORY",n.Outcome);Assert.IsTrue((bool)last["native"]["waveEntry"]["finished"]);Assert.IsFalse(last["native"]["gunnerIntercept"]["projectiles"].Any(x=>(string)x["terminal"]=="FLYING"));Assert.AreEqual(JTokenType.Null,last["residualHazards"].Type);Assert.Throws<InvalidOperationException>(()=>s.RequireTrustedMaintenance());File.WriteAllText(Qa+"actual-terminal.json",last.ToString());}}
  [Test] public void DisposalRejectsLateAcceptedUpdatesAndDoesNotReleaseBorrowedNative(){var n=Native();var s=new BSafeMaintenanceObservationSource(n);s.Dispose();s.Dispose();n.SetPaused("late",true);Assert.IsTrue(n.Paused);Assert.Throws<ObjectDisposedException>(()=>s.ObserveAccepted("late",0));Assert.Throws<ObjectDisposedException>(()=>s.Capture());Assert.Throws<ObjectDisposedException>(()=>s.RequireUnchanged(0,"old"));using(var replacement=new BSafeMaintenanceObservationSource(n)){Assert.AreEqual(0,replacement.Revision);Assert.IsTrue((bool)replacement.Capture()["combatStopped"]);Assert.Throws<InvalidOperationException>(()=>replacement.ObserveAccepted("late",0));}}
 }
}
#endif



